import { render } from '@testing-library/react';
import { describe, expect, it } from 'vitest';
import { linePath, TopPluginsBarChart } from './DashboardPage';

describe('dashboard charts', () => {
  it('uses a shared maximum for line coordinates', () => {
    expect(linePath([50, 0], 100, 100, 10, 100)).toBe('M10.00 50.00 L90.00 90.00');
  });

  it('sizes each bar viewport instead of stretching its corner radius', () => {
    const { container } = render(
      <TopPluginsBarChart
        data={[{
          pluginId: 1,
          namespace: '@semrel',
          name: 'provider-github',
          category: 'provider',
          views: 25,
          downloads: 100,
        }]}
      />,
    );

    const bars = container.querySelectorAll('.top-plugins-bars svg');
    expect(bars[0]).toHaveAttribute('width', '25%');
    expect(bars[1]).toHaveAttribute('width', '100%');
    expect(bars[0]).not.toHaveAttribute('viewBox');
    expect(bars[0].querySelector('rect')).toHaveAttribute('rx', '3');
  });
});
